import React from "react";
import "./../css/form.css";
import {
  FaUser,
  FaPhone,
  FaMapMarkerAlt,
  FaImage,
  FaTag,
  FaQuestionCircle,
  FaClock,
  FaLink,
} from "react-icons/fa";

const API_URL = "https://iranaserviceapp.ir/test/api";

class CustomerRequestForm extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      fullName: "",
      mobile: "",
      landline: "",
      province: "",
      address: "",
      deviceType: "",
      deviceBrand: "",
      deviceIssue: "",
      visitTime: "",
      description: "",

      loading: false,
      message: "",
      error: "",
    };

    this.handleChange = this.handleChange.bind(this);
    this.handleSubmit = this.handleSubmit.bind(this);
  }

  // =========================
  // تغییر فیلدها
  // =========================

  handleChange(field) {
    return (e) => {
      this.setState({
        [field]: e.target.value,
        message: "",
        error: "",
      });
    };
  }

  // =========================
  // ثبت درخواست
  // =========================

  handleSubmit(e) {
    e.preventDefault();

    const {
      fullName,
      mobile,
      landline,
      province,
      address,
      deviceType,
      deviceBrand,
      deviceIssue,
      visitTime,
      description,
    } = this.state;

    // -------------------------
    // اعتبارسنجی ساده
    // -------------------------

    if (!fullName.trim()) {
      this.setState({
        error: "لطفاً نام مشتری را وارد کنید.",
      });

      return;
    }

    if (!mobile.trim()) {
      this.setState({
        error: "لطفاً شماره موبایل را وارد کنید.",
      });

      return;
    }

    if (!province) {
      this.setState({
        error: "لطفاً استان را انتخاب کنید.",
      });

      return;
    }

    if (!deviceType) {
      this.setState({
        error: "لطفاً نوع دستگاه را انتخاب کنید.",
      });

      return;
    }

    if (!deviceBrand) {
      this.setState({
        error: "لطفاً برند دستگاه را انتخاب کنید.",
      });

      return;
    }

    // -------------------------
    // جدا کردن نام و نام خانوادگی
    // -------------------------

    const nameParts = fullName.trim().split(/\s+/);

    const name = nameParts[0] || "";

    const family =
      nameParts.length > 1
        ? nameParts.slice(1).join(" ")
        : "";

    // -------------------------
    // توکن
    // -------------------------

    const token = localStorage.getItem("token");

    if (!token) {
      this.setState({
        error: "دسترسی شما منقضی شده است. لطفاً دوباره وارد شوید.",
      });

      return;
    }

    // -------------------------
    // اطلاعات ارسالی به API
    // -------------------------

    const requestData = {
      name: name,
      family: family,
      mobile: mobile,
      mobile2: landline,
      state: province,
      address: address,
      device_type: deviceType,
      device_brand: deviceBrand,
      problem: deviceIssue,
      time: visitTime,
      description: description,
    };

    console.log("CREATE REQUEST DATA:", requestData);

    this.setState({
      loading: true,
      error: "",
      message: "",
    });

    // -------------------------
    // ارسال به API
    // POST /create
    // -------------------------

    fetch(`${API_URL}/create`, {
      method: "POST",

      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },

      body: JSON.stringify(requestData),
    })
      .then(async (response) => {
        const data = await response.json();

        console.log("CREATE API RESPONSE:", data);

        if (!response.ok) {
          throw new Error(
            data.message || "خطا در ثبت درخواست"
          );
        }

        return data;
      })
      .then((data) => {
        if (String(data.status) === "1") {
          this.setState({
            loading: false,
            message: data.message || "درخواست با موفقیت ثبت شد.",
            error: "",

            fullName: "",
            mobile: "",
            landline: "",
            province: "",
            address: "",
            deviceType: "",
            deviceBrand: "",
            deviceIssue: "",
            visitTime: "",
            description: "",
          });

          return;
        }

        this.setState({
          loading: false,
          error: data.message || "ثبت درخواست انجام نشد.",
          message: "",
        });
      })
      .catch((error) => {
        console.error("CREATE REQUEST ERROR:", error);

        this.setState({
          loading: false,
          error: error.message || "خطایی در ارتباط با سرور رخ داد.",
          message: "",
        });
      });
  }

  render() {
    const {
      fullName,
      mobile,
      landline,
      province,
      address,
      deviceType,
      deviceBrand,
      deviceIssue,
      visitTime,
      description,
      loading,
      message,
      error,
    } = this.state;

    return (
      <div className="container pt-3" dir="rtl">
        <div
          className="mx-auto"
          style={{ maxWidth: "480px" }}
        >
          {/* عنوان */}

          <h6 className="text-center fw-bold text-dark mb-4">
            اطلاعات مشتری را با دقت ثبت کنید
          </h6>

          {/* پیام موفقیت */}

          {message && (
            <div
              className="alert alert-success text-center rounded-3"
              role="alert"
            >
              {message}
            </div>
          )}

          {/* پیام خطا */}

          {error && (
            <div
              className="alert alert-danger text-center rounded-3"
              role="alert"
            >
              {error}
            </div>
          )}

          <form onSubmit={this.handleSubmit}>

            {/* ================= نام کامل ================= */}

            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaUser />
              </div>

              <input
                type="text"
                placeholder="نام کامل"
                value={fullName}
                onChange={this.handleChange("fullName")}
              />
            </div>

            {/* ================= موبایل ================= */}

            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaPhone />
              </div>

              <input
                type="tel"
                inputMode="numeric"
                placeholder="شماره موبایل"
                value={mobile}
                onChange={this.handleChange("mobile")}
              />
            </div>

            {/* ================= تلفن ثابت ================= */}

            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaPhone />
              </div>

              <input
                type="tel"
                inputMode="numeric"
                placeholder="تلفن ثابت"
                value={landline}
                onChange={this.handleChange("landline")}
              />
            </div>

            {/* ================= استان ================= */}

            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaMapMarkerAlt />
              </div>

              <select
                value={province}
                onChange={this.handleChange("province")}
              >
                <option value="" disabled>
                  استان
                </option>

                <option value="1">
                  یزد
                </option>

                <option value="2">
                  تهران
                </option>

                <option value="3">
                  اصفهان
                </option>

                <option value="4">
                  فارس
                </option>

                <option value="5">
                  خراسان رضوی
                </option>

                <option value="6">
                  البرز
                </option>
              </select>
            </div>

            {/* ================= آدرس ================= */}

            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaMapMarkerAlt />
              </div>

              <input
                type="text"
                placeholder="آدرس"
                value={address}
                onChange={this.handleChange("address")}
              />
            </div>

            {/* ================= نوع دستگاه ================= */}

            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaImage />
              </div>

              <select
                value={deviceType}
                onChange={this.handleChange("deviceType")}
              >
                <option value="" disabled>
                  نوع دستگاه
                </option>

                <option value="washer">
                  ماشین لباسشویی
                </option>

                <option value="fridge">
                  یخچال
                </option>

                <option value="ac">
                  کولر گازی
                </option>

                <option value="tv">
                  تلویزیون
                </option>
              </select>
            </div>

            {/* ================= برند دستگاه ================= */}

            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaTag />
              </div>

              <select
                value={deviceBrand}
                onChange={this.handleChange("deviceBrand")}
              >
                <option value="" disabled>
                  برند دستگاه
                </option>

                <option value="samsung">
                  سامسونگ
                </option>

                <option value="lg">
                  ال‌جی
                </option>

                <option value="snowa">
                  اسنوا
                </option>

                <option value="pakshoma">
                  پاکشوما
                </option>
              </select>
            </div>

            {/* ================= ایراد دستگاه ================= */}

            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaQuestionCircle />
              </div>

              <input
                type="text"
                placeholder="ایراد دستگاه"
                value={deviceIssue}
                onChange={this.handleChange("deviceIssue")}
              />
            </div>

            {/* ================= زمان مراجعه ================= */}

            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaClock />
              </div>

              <input
                type="text"
                placeholder="زمان مراجعه"
                value={visitTime}
                onChange={this.handleChange("visitTime")}
              />
            </div>

            {/* ================= توضیحات ================= */}

            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaLink />
              </div>

              <input
                type="text"
                placeholder="توضیحات"
                value={description}
                onChange={this.handleChange("description")}
              />
            </div>

            {/* ================= دکمه ثبت ================= */}

            <button
              type="submit"
              disabled={loading}
              className="btn btn-sub w-100 fw-bold py-2 rounded-4"
            >
              <small>
                {loading
                  ? "در حال ثبت..."
                  : "ثبت درخواست"}
              </small>
            </button>

          </form>
        </div>
      </div>
    );
  }
}

export default CustomerRequestForm;
